/// A latitude/longitude as a 2 dimensional point. It can be represented in various ways:
/// - as a `{lat, long}` object
/// - as a geo hash value
/// - as a `[lon, lat]` array
/// - as a string in `"<lat>, <lon>"` or WKT point formats
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub enum GeoLocation {
    LatLonGeoLocation(LatLonGeoLocation),
    GeoHashLocation(GeoHashLocation),
    DoubleList(Vec<crate::typed::support::Float64>),
    String(String),
}

impl From<LatLonGeoLocation> for GeoLocation {
    fn from(value: LatLonGeoLocation) -> Self {
        GeoLocation::LatLonGeoLocation(value)
    }
}

impl From<GeoHashLocation> for GeoLocation {
    fn from(value: GeoHashLocation) -> Self {
        GeoLocation::GeoHashLocation(value)
    }
}

impl From<Vec<crate::typed::support::Float64>> for GeoLocation {
    fn from(value: Vec<crate::typed::support::Float64>) -> Self {
        GeoLocation::DoubleList(value)
    }
}

impl From<String> for GeoLocation {
    fn from(value: String) -> Self {
        GeoLocation::String(value)
    }
}

impl From<&str> for GeoLocation {
    fn from(value: &str) -> Self {
        GeoLocation::String(value.into())
    }
}

/// A GeoJson shape, that can also use Elasticsearch's `envelope` extension.
pub type GeoShape = serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub enum GeoShapeRelation {
    /// Return all documents whose `geo_shape` or `geo_point` field intersects the query geometry.
    #[serde(rename = "intersects")]
    Intersects,
    /// Return all documents whose `geo_shape` or `geo_point` field has nothing in common with the query geometry.
    #[serde(rename = "disjoint")]
    Disjoint,
    /// Return all documents whose `geo_shape` or `geo_point` field is within the query geometry.
    /// Line geometries are not supported.
    #[serde(rename = "within")]
    Within,
    /// Return all documents whose `geo_shape` or `geo_point` field contains the query geometry.
    #[serde(rename = "contains")]
    Contains,
}

