pub struct ShardFailure {
    #[serde(alias = "_index", default, skip_serializing_if = "Option::is_none")]
    pub index: Option<IndexName>,
    #[serde(alias = "_node", default, skip_serializing_if = "Option::is_none")]
    pub node: Option<String>,
    pub reason: ErrorCause,
    #[serde(alias = "_shard", default, skip_serializing_if = "Option::is_none")]
    pub shard: Option<i32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub primary: Option<bool>,
}

impl ShardFailure {
    /// Creates a builder for [`ShardFailure`].
    ///
    /// Required: `reason`.
    pub fn builder() -> ShardFailureBuilder {
        ShardFailureBuilder::new()
    }

    /// Creates a [`ShardFailure`] from a function that sets the members of its builder.
    ///
    /// Required: `reason`.
    pub fn of<B: crate::typed::builder::Build<Output = ShardFailure>>(
        f: impl FnOnce(ShardFailureBuilder) -> B,
    ) -> ShardFailure {
        f(Self::builder()).build()
    }
}

